source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(grid[rr][cc] == 3
                    for rr in range(r - 1, r + 2)
                    for cc in range(c - 1, c + 2) if (rr, cc) != (r, c)):
                markers.append((r, c))
    marker_set = set(markers)

    for r, c in markers:
        row_line = sum(v == 2 for v in grid[r])
        col_line = sum(grid[i][c] == 2 for i in range(h))
        if row_line >= col_line:
            # Extend across the perpendicular divider lines.
            for i in range(h):
                if out[i][c] == 0:
                    out[i][c] = 1
            dividers = [i for i in range(h) if sum(v == 2 for v in grid[i]) >= w * 0.6]
            for i in dividers:
                if (i, c) not in marker_set:
                    for rr in range(max(0, i - 1), min(h, i + 2)):
                        for cc in range(max(0, c - 1), min(w, c + 2)):
                            if (rr, cc) != (i, c):
                                out[rr][cc] = 1
        else:
            for j in range(w):
                if out[r][j] == 0:
                    out[r][j] = 1
            dividers = [j for j in range(w) if sum(grid[i][j] == 2 for i in range(h)) >= h * 0.6]
            for j in dividers:
                if (r, j) not in marker_set:
                    for rr in range(max(0, r - 1), min(h, r + 2)):
                        for cc in range(max(0, j - 1), min(w, j + 2)):
                            if (rr, cc) != (r, j):
                                out[rr][cc] = 1
    return out
'''
